using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Text;
namespace PZ3D {static class NativeLaunchLatencyTests {
 static void Check(bool value,string why){if(!value)throw new Exception("FAIL: "+why);Console.WriteLine("PASS: "+why);}
 static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
 static T Measure<T>(string phase,Func<T> work){var watch=Stopwatch.StartNew();var result=work();Console.WriteLine(phase+"Ms="+watch.ElapsedMilliseconds);return result;}
 static void Timing(){string root=Path.Combine(Path.GetTempPath(),"ozl-launch-timing-"+Guid.NewGuid().ToString("N"));try{var e=new Engine(Path.Combine(root,"steamapps","common","ProjectZomboid"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Put(e.Config,"{\"vmArgs\":[]}");Put(e.Mods,"VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n");var phases=new List<string>();var request=new ProfileLaunchRequest{Kind="normal",ValidateBeforeStage=()=>phases.Add("validation")};request.Timing=(phase,elapsed)=>{Check(elapsed>=0,"phase elapsed time is monotonic");phases.Add(phase);};LaunchProfiles.Stage(e,request);Check(phases.SequenceEqual(new[]{"stage-plan","validation","stage-write"}),"native staging reports actual planning and writing around final validation");LaunchProfiles.Recover(e,true);Check(!LaunchProfiles.Pending(e),"timed synthetic stage recovers its session");request.Timing=(phase,elapsed)=>{throw new IOException("fixture diagnostic failure");};LaunchProfiles.Stage(e,request);Check(LaunchProfiles.Pending(e),"timing observer failure cannot prevent a valid staging transaction");LaunchProfiles.Recover(e,true);}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
 // These modes never instantiate a controller, initialize Steam, or start a client.
 // Stage reads the supplied game but writes only disposable user/data fixture paths.
 static void Actual(string[] args){var e=new Engine(args[1],args[2],args[3],true);var selected=SaveProfiles.DefaultMods(File.ReadAllBytes(e.Mods));var translation=Measure("translationBuild",()=>ServerLaunchTranslations.Build(e,selected));Console.WriteLine("translationFiles="+translation.Count+" translationBytes="+translation.Sum(p=>(long)p.Value.Length));var budget=new LaunchReadBudget(16777216);budget.Capture();var warnings=new List<string>();var catalog=Measure("catalog",()=>SaveProfiles.PreflightEntries(e,selected,warnings,budget));Measure("catalogEvidence",()=>{budget.Evidence.Validate();return 0;});GC.KeepAlive(catalog);if(args[0]=="--actual-readonly")return;
  string root=Path.Combine(Path.GetTempPath(),"ozl-launch-stage-"+Guid.NewGuid().ToString("N"));try{var fixture=new Engine(e.Game,Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(Path.GetDirectoryName(fixture.Mods));File.Copy(e.Mods,fixture.Mods);for(int n=0;n<2;n++){var request=new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=1,Username="fixture"};request.Timing=(phase,elapsed)=>Console.WriteLine(phase+"Ms="+elapsed);Measure("stage",()=>{LaunchProfiles.Stage(fixture,request);return 0;});Measure("recover",()=>LaunchProfiles.Recover(fixture,true));}}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
 public static int Main(string[] args){try{if(args.Length==4&&(args[0]=="--actual-readonly"||args[0]=="--actual-stage"))Actual(args);else Timing();return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
}}
